import{_ as a,o as t,c as r,ag as o}from"./chunks/framework.BuUvxvtQ.js";const u=JSON.parse('{"title":"Web App Guide","description":"","frontmatter":{},"headers":[],"relativePath":"web-app.md","filePath":"web-app.md"}'),s={name:"web-app.md"};function n(i,e,l,d,p,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="web-app-guide" tabindex="-1">Web App Guide <a class="header-anchor" href="#web-app-guide" aria-label="Permalink to &quot;Web App Guide&quot;">​</a></h1><p>Sky Style combines live weather, your saved closet, and an AI recommendation in one dashboard. This guide is split into focused pages covering each area of the app.</p><h2 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h2><ol><li>Create an account at <a href="https://skystyle.app" target="_blank" rel="noreferrer">skystyle.app</a> by signing in with GitHub or Google.</li><li>On the dashboard, choose a location manually or permit location access.</li><li>Add the clothes you actually own in <strong>Closet</strong>.</li><li>Generate a recommendation and use follow-up questions to refine it.</li></ol><p>New here? Try the <a href="https://skystyle.app/#demo" target="_blank" rel="noreferrer">no-login Live Demo</a> first to see real weather data.</p><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><ul><li><strong><a href="/web-app/dev-center.html">Dev Center</a></strong> — task-based support, monitoring and account tools for authorised developers.</li></ul><p><strong>Start here:</strong></p><ul><li><strong><a href="/web-app/getting-started.html">Getting Started</a></strong> — a step-by-step walkthrough from sign-up to your first refined recommendation.</li><li><strong><a href="/web-app/how-it-works.html">How It Works</a></strong> — the end-to-end flow, weather sources, AI models, accuracy scoring, and usage limits.</li></ul><p><strong>Feature reference:</strong></p><ul><li><strong><a href="/web-app/dashboard.html">Dashboard &amp; Closet</a></strong> — recommendation modes, weather planning panel, model switching, follow-up questions, BYOK, and your wardrobe.</li><li><strong><a href="./web-app/shop.html">Shop</a></strong> — your budget range, sourced product widgets, shared AI models, and source availability.</li><li><strong><a href="/web-app/settings.html">Settings</a></strong> — profile, units, appearance, preferences, dashboard behaviour, layout &amp; spacing, and tutorials.</li><li><strong><a href="/web-app/security-and-privacy.html">Security &amp; Privacy</a></strong> — 2FA, passkeys, API keys, security log, data export, and account deletion.</li><li><strong><a href="/web-app/automatic-recommendations.html">Automatic Recommendations</a></strong> — schedule exact-time outfit recommendations with a manual location.</li><li><strong><a href="/web-app/api-dashboard.html">API Dashboard</a></strong> — manage API keys, allocate credits, and view per-key balances.</li><li><strong><a href="/web-app/account-and-support.html">Account &amp; Support</a></strong> — the account hub, plans, feedback, inbox, changelog, and service status.</li></ul><p><strong>Advanced:</strong></p><ul><li><strong><a href="/web-app/custom-weather-sources.html">Custom Weather Sources</a></strong> — (Pro) add your own HTTPS weather sources with SSRF-safe validation.</li></ul><p><strong>Need help?</strong></p><ul><li><strong><a href="/web-app/faq.html">FAQ &amp; Troubleshooting</a></strong> — common questions, error explanations, and fixes.</li></ul><h2 id="usage-and-credits" tabindex="-1">Usage and credits <a class="header-anchor" href="#usage-and-credits" aria-label="Permalink to &quot;Usage and credits&quot;">​</a></h2><p>Your account and dashboard show the current allowance and balance. Checkout and credit purchases are unavailable. See <a href="/web-app/how-it-works.html#usage-limits">usage limits</a> and <a href="/web-app/api-dashboard.html#credits-and-usage">API credits</a>.</p>',17)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
